// Normalizar datos recibidos por el webhook de Next.js
const raw = $json.body || $json;

let numberFormatted = String(raw.numberFormatted || raw.whatsapp || '').replace(/\D/g, '');
if (numberFormatted.length === 10) {
  numberFormatted = '52' + numberFormatted;
} else if (numberFormatted.length === 13 && numberFormatted.startsWith('521')) {
  numberFormatted = '52' + numberFormatted.substring(3);
}

return [{
  json: {
    leadId: raw.leadId || '',
    folioCode: raw.folioCode || '',
    nombre: raw.nombre || '',
    nombreNegocio: raw.nombreNegocio || '',
    whatsapp: raw.whatsapp || '',
    numberFormatted,
    tipo: raw.tipo || 'descarga',
    texto: raw.texto || '',
    link: raw.link || '',
    dias: raw.dias || 1,
    horas: raw.horas || 0,
    recibidoEn: new Date().toISOString()
  }
}];
